import sys

data = sys.stdin.read().split()
n = int(data[0])
a = list(map(int, data[1:1 + n]))
def dmin(v):
    m = 9
    while v:
        if v % 10 < m:
            m = v % 10
        v //= 10
    return m
c = 0
for idx in range(n - 1):
    if (dmin(a[idx]) < 3) and (dmin(a[idx + 1]) < 3):
        c += 1
print(c)

